fun tr(lang: String, key: String): String = words[key]?.get(languages.keys.indexOf(lang).coerceAtLeast(0)) ?: key

fun reminderAdvanceText(language: String, days: Int): String = "$days ${tr(language, if(days==1) "daysBeforeOne" else "daysBeforeMany")}"
